action.mutation:
mutation CreateCustomer($payload: [CustomerCreatePayloadInput!]!) {
  mutation: createCustomer(payload: $payload) { 
    id
    code
  }
}

mutation UpdateCustomer($payload: [CustomerUpdatePayloadInput!]!) {
  mutation: updateCustomer(payload: $payload) { 
    id
    code
  }
}

mutation CreateSupplierAddress($payload: [CustomerAddressCreatePayloadInput!]!) {
  address: createCustomerAddress(payload: $payload) { 
    id
    code
  }
}

mutation DeleteCustomer($payload: [CustomerDeletePayloadInput!]!) {
  mutation: deleteCustomer(payload: $payload) { 
    id
    code
  }
}

mutation CreateCustomerProduct($payload: [CustomerProductCreatePayloadInput!]!) {
  mutation: createCustomerProduct(payload: $payload) { 
    id
    number
  }
}

mutation UpdateCustomerProduct($payload: [CustomerProductUpdatePayloadInput!]!) {
  mutation: updateCustomerProduct(payload: $payload) { 
    id
    number
  }
}
